const HALLOWEEN_2025_EXTRAS={"pumpking":{"level":"Solo boss — recommended level depends on the source guide","type":"Event boss","rules":["One Special Candy per attempt, obtained from mini-bosses.","Bring six distinct Pokémon species with different held items; three Pokémon fight simultaneously.","Hard mode unlocks after the first victory.","The sourced routes depend on summoned adds and RNG."],"guideVideos":[{"name":"Smooge · 2025 Pumpking hard-mode strategy 2025","url":"https://www.youtube.com/watch?v=tfSJuAeaQ3Q","description":"Team uses Krookodile and Galvantula. The original guide recommends Hasty Galvantula; Smooge also tested Timid, sometimes replacing X Attack with healing. Review exact benchmarks in the video."},{"name":"lasaGna · construction d'équipe difficile 2025","url":"https://www.youtube.com/watch?v=htTdOEO1Y1k","description":"Includes breeding guidance for Gothitelle and Aerodactyl. The indexed video description does not supply all six exact builds."},{"name":"PAXPO · Pumpking difficile 2025","url":"https://www.youtube.com/watch?v=EaAR1BhlQ6o","description":"The video mentions a Poképaste and a rotation, but indexed URLs were truncated."}],"notices":["SenseiN3SS's 2025 guide reports an Aftermath change affecting Drifblim and phase 3. Old turn routes may no longer work.","Community reports suggest the historical Krookodile / Tropius / Chandelure strategy could fail during the 2025 event; success must not be guaranteed.","Smooge's November 5, 2025 video discusses EV adjustments for Krookodile and a nature change for Galvantula, without listing all six complete builds."],"sources":["https://forums.pokemmo.com/index.php?/topic/192700-Trick-or-Treat-2025-the-ultimate-Trick-or-Treat-event-guide/","https://forums.pokemmo.com/index.php?/topic/150294-eng-es-Trick-or-Treat-preparation-guide-to-make-profits/","https://www.youtube.com/watch?v=tfSJuAeaQ3Q"]},"galvantula":{"level":"Level 60 · 1 OT Pokémon","type":"Bug / Electric","heldItem":"Wise Glasses","bossMoves":["Coup d'Jus","Bug Buzz","Giga Drain","Thunder"],"weakness":["Feu","Roche"],"rules":["Each player must bring different Pokémon species and held items.","After Light Screen at 75% HP, prioritize physical Fire-type moves during turn two.","P3 and P4 use Defog on turn three; the source specifies another Tailwind on turn five."],"historical":["Ninetales","Entei","Chandelure","Darmanitan","Blaziken","Infernape"],"guideVideos":[{"name":"caav · Galvantula 3★ 2025","url":"https://www.youtube.com/watch?v=rxINO6Zb9RU","description":"Video covering caav's rotation, referring to the Big Info Doc PDF."}],"sources":["https://mmobreeder.com/fr/raids/galvantula","https://forums.pokemmo.com/index.php?/topic/150294-eng-es-Trick-or-Treat-preparation-guide-to-make-profits/"]},"banette":{"level":"Level 60 · 1 OT Pokémon","type":"Ghost","ability":"Cursed Body","heldItem":"Sitrus Berry","bossMoves":["Poing-Glace","Dark Pulse","Thunderbolt","Shadow Claw"],"weakness":["Spectre","Ténèbres"],"rules":["Do not duplicate species or held items.","Turn one: set sun and use Incinerate to consume Sitrus Berry.","The remainder of caav's 2025 route relies on Flamethrower; Cotton Guard can disrupt physical damage."],"historical":["Gengar","Chandelure","Mismagius","Bisharp","Hydreigon","Tyranitar","Crawdaunt","Weavile","Krookodile"],"sources":["https://mmobreeder.com/fr/raids/banette","https://forums.pokemmo.com/index.php?/topic/150294-eng-es-Trick-or-Treat-preparation-guide-to-make-profits/"]},"hypno":{"level":"Level 60 · 1 OT Pokémon","type":"Psychic","bossMoves":["Psychic","Foul Play","Focus Blast","Grass Knot"],"weakness":["Insecte","Ténèbres","Spectre"],"rules":["Do not duplicate Pokémon species or held items.","Reset if the summoned add is Tyranitar in the caav strategy.","Safeguard limits Hypnosis; Defog removes Reflect.","One player uses Trick Room on turn two to cancel the boss's Trick Room.","The reversed type chart near 33% HP changes attack priorities."],"historical":["Gengar","Chandelure","Mismagius","Bisharp","Hydreigon","Tyranitar","Weavile","Heracross","Volcarona"],"sources":["https://mmobreeder.com/fr/raids/hypno","https://forums.pokemmo.com/index.php?/topic/150294-eng-es-Trick-or-Treat-preparation-guide-to-make-profits/"]},"golurk":{"level":"Level 60 · 1 OT Pokémon","type":"Ground / Ghost","bossMoves":["Vampipoing","Earthquake","Poing-Glace","Shadow Punch"],"weakness":["Eau","Plante","Glace","Spectre","Ténèbres"],"rules":["Do not duplicate Pokémon species or held items.","Set rain and Tailwind on turn one, then Defog away Stealth Rock.","Avoid Rock, Steel and Dark Pokémon (such as Crawdaunt, Empoleon, Omastar, Kabutops) that may attract healing Drain Punch.","After support moves, caav's route favors Water-type attacks."],"historical":["Gengar","Chandelure","Mismagius","Bisharp","Hydreigon","Tyranitar","Weavile","Kingdra","Cloyster","Articuno","Vanilluxe","Abomasnow"],"guideVideos":[{"name":"caav · Golurk 3★ 2025","url":"https://www.youtube.com/watch?v=CtUt0w8BUg4","description":"Demonstrates a Rain Dance + Tailwind + Water-type attack strategy."}],"sources":["https://mmobreeder.com/fr/raids/golurk","https://forums.pokemmo.com/index.php?/topic/150294-eng-es-Trick-or-Treat-preparation-guide-to-make-profits/"]},"scolipede":{"level":"Level 80 · 1 OT Pokémon","type":"Bug / Poison","ability":"Speed Boost","heldItem":"Sitrus Berry","bossMoves":["Rock Slide","Earthquake","Megahorn","Hydroqueue"],"weakness":["Feu","Vol","Psy","Roche"],"rules":["Do not duplicate Pokémon species or held items.","Turn one: use Sunny Day and Incinerate to remove Sitrus Berry.","Use special Fire-type attacks while the boss's Defense is boosted.","Use Haze on turn three and again on turn five with Tailwind support.","Speed Boost makes Speed benchmarks crucial: switch slow attackers in at the planned times."],"historical":["Ninetales","Entei","Chandelure","Darmanitan","Blaziken","Infernape","Excadrill","Braviary","Staraptor","Togekiss"],"sources":["https://mmobreeder.com/fr/raids/scolipede","https://forums.pokemmo.com/index.php?/topic/150294-eng-es-Trick-or-Treat-preparation-guide-to-make-profits/"]},"mandibuzz":{"level":"Level 80 · 1 OT Pokémon","type":"Dark / Flying","bossMoves":["Tranch'Air","Dark Pulse","Heat Wave","Snarl"],"weakness":["Électrik","Glace","Roche","Fée (non disponible comme type offensif classique dans PokeMMO)"],"rules":["Do not duplicate Pokémon species or held items.","The boss's violent wind mechanic forces switches at the end of each turn.","Set rain and Tailwind on turn one.","Use Thunder, not Thunderbolt. Use Haze without Prankster after Nasty Plot (turns three and five)."],"historical":["Tyranitar","Excadrill","Zapdos","Magnezone","Raikou","Ampharos","Cloyster","Articuno","Weavile"],"sources":["https://mmobreeder.com/fr/raids/mandibuzz","https://forums.pokemmo.com/index.php?/topic/150294-eng-es-Trick-or-Treat-preparation-guide-to-make-profits/"]},"absol":{"level":"Level 80 · 1 OT Pokémon","type":"Dark","bossMoves":["Psycho Cut","Close Combat","Night Slash","Rock Slide"],"weakness":["Combat","Insecte"],"rules":["Do not duplicate Pokémon species or held items.","Bad Luck causes random disruptions during battle.","Set Tailwind at the beginning and again on turn five; prioritize Fighting moves.","Use Heal Block before Wish to prevent healing.","Super-effective moves without STAB may also reach the raid damage cap."],"historical":["Volcarona","Blaziken","Infernape","Heracross","Primeape","Medicham","Gallade","Machamp","Conkeldurr","Toxicroak","Breloom"],"sources":["https://mmobreeder.com/fr/raids/absol","https://forums.pokemmo.com/index.php?/topic/150294-eng-es-Trick-or-Treat-preparation-guide-to-make-profits/"]},"darkrai":{"level":"4★ level 95 · 5★ level 100","type":"Dark","bossMoves":["Focus Blast","Dark Pulse","Psyshock","Snarl"],"weakness":["Combat","Insecte"],"rules":["Complete all seven prerequisite raids to access Newmoon Island.","Open with Chesto Berry or Vital Spirit to counter Dark Void.","The 4★ and 5★ Darkrai routes differ; never mix them.","The caav 5★ source documents reversed type interactions on turns four and six (and seven if needed), plus physical/special inversion near 25% HP."],"historical":["Volcarona","Blaziken","Infernape","Heracross","Primeape","Medicham","Gallade","Machamp","Conkeldurr","Toxicroak","Breloom"],"sources":["https://mmobreeder.com/fr/raids/darkrai","https://forums.pokemmo.com/index.php?/topic/150294-eng-es-Trick-or-Treat-preparation-guide-to-make-profits/"]}};
